import { execution } from "@dynatrace-sdk/automation-utils";

async function getText(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`HTTP ${resp.status} for ${url}`);
  return await resp.text();
}

export default async function () {
  await execution();

  const docsSitemapUrlUi = "{{ event().inputs.docsSitemapUrl }}";
  const docsSitemapUrl = (!docsSitemapUrlUi || docsSitemapUrlUi.startsWith("{{")) ? "https://docs.dynatrace.com/docs/sitemap.xml" : docsSitemapUrlUi;

  const sitemap = await getText(docsSitemapUrl);
  const matches = [...sitemap.matchAll(/oneagent\/sprint-(\d+)/g)].map((m) => Number(m[1]));
  if (!matches.length) throw new Error('No sprint links found in docs sitemap');

  const latestSprint = Math.max(...matches);
  const latestRelease = `1.${latestSprint}`;
  const sprintUrl = `https://docs.dynatrace.com/docs/whats-new/oneagent/sprint-${latestSprint}`;
  const sprintHtml = await getText(sprintUrl);

  const essMatch = sprintHtml.match(/Enterprise Success and Support[\s\S]*?(1\.\d{3})/i);
  if (!essMatch) throw new Error('Could not parse ESS oldest supported version');
  const oldestSupportedEss = essMatch[1];

  return {
    latest_release: latestRelease,
    oldest_supported_ess: oldestSupportedEss,
    fetched_at: new Date().toISOString(),
    source_url: sprintUrl
  };
}

import { result } from "@dynatrace-sdk/automation-utils";
import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

// Set to a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).
// Token needs: events.ingest
const RUM_TOKEN_VAULT_ID_UI = "{{ event().inputs.rumTokenVaultId }}";
const RUM_TOKEN_VAULT_ID = (!RUM_TOKEN_VAULT_ID_UI || RUM_TOKEN_VAULT_ID_UI.startsWith("{{")) ? "CREDENTIALS_VAULT-152083F2EC7D5E4B" : RUM_TOKEN_VAULT_ID_UI;

async function resolveToken(id) {
  const normalized = (id || '').trim();
  if (!normalized) throw new Error('RUM_TOKEN_VAULT_ID is empty.');
  if (!normalized.startsWith('CREDENTIALS_VAULT-')) {
    throw new Error('RUM_TOKEN_VAULT_ID must be a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).');
  }

  const credentials = await credentialVaultClient.getCredentialsDetails({ id: normalized });
  if (!credentials || !credentials.token) {
    throw new Error(`No token found in vault entry ${normalized}. Ensure the entry type is "Token" and the workflow has access.`);
  }
  return credentials.token;
}

export default async function () {
  if (RUM_TOKEN_VAULT_ID.includes('YOUR_CREDENTIAL_ID')) {
    throw new Error('Set RUM_TOKEN_VAULT_ID to a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).');
  }

  const versions = await result('oneagent_collect_release_baseline');
  const apiToken = await resolveToken(RUM_TOKEN_VAULT_ID);

  const envUrl = (getEnvironmentUrl() || '').trim();
  if (!envUrl) throw new Error('getEnvironmentUrl() returned an empty value.');

  const env = new URL(envUrl);
  env.host = env.host.replace('.apps.', '.');
  env.pathname = '';
  env.search = '';
  env.hash = '';

  const baseUrl = env.toString().replace(/\/$/, '');

  const event = {
    eventType: 'CUSTOM_ANNOTATION',
    title: `OneAgentBaseline|${versions.latest_release}|${versions.oldest_supported_ess}|${versions.fetched_at}`,
    description: `OneAgent release baseline sync from ${versions.source_url}`,
    properties: {
      latest_release: versions.latest_release,
      oldest_supported_ess: versions.oldest_supported_ess,
      fetched_at: versions.fetched_at,
      source_url: versions.source_url
    }
  };

  const resp = await fetch(`${baseUrl}/api/v2/events/ingest`, {
    method: 'POST',
    headers: {
      Authorization: `Api-Token ${apiToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(event)
  });

  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`Events ingest failed: HTTP 401 ${body}. Token authentication failed for vault credential ${RUM_TOKEN_VAULT_ID}.`);
    }
    throw new Error(`Events ingest failed: HTTP ${resp.status} ${body}`);
  }

  return { stored: true };
}

import { execution } from "@dynatrace-sdk/automation-utils";
import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

// Set to a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).
// Token needs: RumJavaScriptTagManagement + events.ingest
// Optional for human-readable tag labels: rumManualInsertionTags.read
const RUM_TOKEN_VAULT_ID_UI = "{{ event().inputs.rumTokenVaultId }}";
const RUM_TOKEN_VAULT_ID = (!RUM_TOKEN_VAULT_ID_UI || RUM_TOKEN_VAULT_ID_UI.startsWith("{{")) ? "CREDENTIALS_VAULT-152083F2EC7D5E4B" : RUM_TOKEN_VAULT_ID_UI;
let DT_API_TOKEN = "";

async function loadToken() {
  if (RUM_TOKEN_VAULT_ID.includes("YOUR_CREDENTIAL_ID")) {
    throw new Error("Set RUM_TOKEN_VAULT_ID to a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).");
  }

  const normalized = (RUM_TOKEN_VAULT_ID || "").trim();
  if (!normalized) throw new Error("RUM_TOKEN_VAULT_ID is empty.");
  if (!normalized.startsWith("CREDENTIALS_VAULT-")) {
    throw new Error("RUM_TOKEN_VAULT_ID must be a Credential Vault ID (CREDENTIALS_VAULT-xxxxxxxxxxxxxxxx).");
  }

  const credentials = await credentialVaultClient.getCredentialsDetails({ id: normalized });
  if (!credentials || !credentials.token) {
    throw new Error(`No token found in vault entry ${normalized}. Ensure the entry type is \"Token\" and the workflow has access.`);
  }
  DT_API_TOKEN = credentials.token;
}

async function dtGetJson(url) {
  const resp = await fetch(url, { headers: { Authorization: `Api-Token ${DT_API_TOKEN}` } });
  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`GET ${url} failed: HTTP 401 ${body}. Token authentication failed for vault credential ${RUM_TOKEN_VAULT_ID}.`);
    }
    throw new Error(`GET ${url} failed: HTTP ${resp.status} ${body}`);
  }
  return await resp.json();
}

async function dtGetText(url) {
  const resp = await fetch(url, { headers: { Authorization: `Api-Token ${DT_API_TOKEN}` } });
  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`GET ${url} failed: HTTP 401 ${body}. Token authentication failed for vault credential ${RUM_TOKEN_VAULT_ID}.`);
    }
    throw new Error(`GET ${url} failed: HTTP ${resp.status} ${body}`);
  }
  return (await resp.text()).trim();
}

async function dtTryGetText(url) {
  const resp = await fetch(url, { headers: { Authorization: `Api-Token ${DT_API_TOKEN}` } });
  if (!resp.ok) {
    return "";
  }
  return await resp.text();
}

async function dtPostJson(url, payload) {
  const resp = await fetch(url, {
    method: "POST",
    headers: { Authorization: `Api-Token ${DT_API_TOKEN}`, "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  if (!resp.ok) {
    const body = await resp.text();
    if (resp.status == 401) {
      throw new Error(`POST ${url} failed: HTTP 401 ${body}. Token authentication failed for vault credential ${RUM_TOKEN_VAULT_ID}.`);
    }
    throw new Error(`POST ${url} failed: HTTP ${resp.status} ${body}`);
  }
  return await resp.text();
}

function normalizeVersion(value) {
  if (value === null || value === undefined) return "";
  return String(value).trim();
}

function toComparableBigInt(value) {
  const normalized = normalizeVersion(value);
  if (!/^\d+$/.test(normalized)) return null;
  return BigInt(normalized);
}

function pickSupportFloor(configuredVersions) {
  const candidates = [
    normalizeVersion(configuredVersions.latestIESupported),
    normalizeVersion(configuredVersions.latestIE11Supported)
  ].filter((v) => /^\d+$/.test(v));

  if (!candidates.length) return "";
  return candidates.reduce((min, current) => {
    if (BigInt(current) < BigInt(min)) return current;
    return min;
  });
}

function pickEffectiveTarget(configuredVersions, latestVersion) {
  const custom = normalizeVersion(configuredVersions.custom);
  if (/^\d+$/.test(custom) && custom !== "0") {
    return { targetVersion: custom, targetPolicy: "custom" };
  }

  const latestStable = normalizeVersion(configuredVersions.latestStable);
  if (/^\d+$/.test(latestStable)) {
    return { targetVersion: latestStable, targetPolicy: "latest_stable" };
  }

  const previousStable = normalizeVersion(configuredVersions.previousStable);
  if (/^\d+$/.test(previousStable)) {
    return { targetVersion: previousStable, targetPolicy: "previous_stable_fallback" };
  }

  return { targetVersion: normalizeVersion(latestVersion), targetPolicy: "latest_available_fallback" };
}

function computePolicyStatus(currentVersion, targetVersion, supportFloorVersion) {
  const currentBig = toComparableBigInt(currentVersion);
  const targetBig = toComparableBigInt(targetVersion);
  const supportFloorBig = toComparableBigInt(supportFloorVersion);

  if (currentBig === null || targetBig === null) {
    return "unknown";
  }
  if (supportFloorBig !== null && currentBig < supportFloorBig) {
    return "unsupported";
  }
  if (currentBig === targetBig) {
    return "on_target";
  }
  if (currentBig > targetBig) {
    return "above_target";
  }
  return "below_target";
}

function extractHumanReadableVersionLabel(text) {
  const source = String(text || "");
  const patterns = [
    /\b1\.\d+\.\d+\.\d{8}-\d{6}\b/,
    /\b1\.\d+\.\d+\.\d+\.\d{8}-\d{6}\b/,
    /\b1\.\d+\.\d+\.\d{8}\b/
  ];

  for (const pattern of patterns) {
    const match = source.match(pattern);
    if (match) {
      return match[0];
    }
  }
  return "";
}

function summarizeTargetLabel(apps) {
  const labels = [...new Set(apps.map((app) => normalizeVersion(app.humanReadableTargetLabel)).filter(Boolean))];
  if (labels.length === 1) return labels[0];
  return "";
}

async function mapConcurrent(items, concurrency, fn) {
  const out = new Array(items.length);
  let idx = 0;
  async function worker() {
    while (true) {
      const current = idx++;
      if (current >= items.length) return;
      out[current] = await fn(items[current], current);
    }
  }
  await Promise.all(Array.from({ length: Math.min(concurrency, Math.max(1, items.length)) }, worker));
  return out;
}

export default async function () {
  await execution();
  await loadToken();

  const envUrl = (getEnvironmentUrl() || "").trim();
  if (!envUrl) throw new Error("getEnvironmentUrl() returned an empty value.");

  const env = new URL(envUrl);
  env.host = env.host.replace(".apps.", ".");
  env.pathname = "";
  env.search = "";
  env.hash = "";

  const baseUrl = env.toString().replace(/\/$/, "");
  const fetchedAt = new Date().toISOString();

  const manualApps = await dtGetJson(`${baseUrl}/api/v1/rum/manualApps`);
  if (!Array.isArray(manualApps)) throw new Error("Expected /api/v1/rum/manualApps to return an array");

  const latestVersion = normalizeVersion(await dtGetText(`${baseUrl}/api/v1/rum/jsLatestVersion`));
  const configuredVersions = await dtGetJson(`${baseUrl}/api/v1/rum/jsConfiguredVersions`);
  const { targetVersion, targetPolicy } = pickEffectiveTarget(configuredVersions, latestVersion);
  const supportFloorVersion = pickSupportFloor(configuredVersions);
  const oldestSupportedVersion = supportFloorVersion || "N/A";

  if (!latestVersion) throw new Error("Could not resolve latest RUM Classic JS version from /api/v1/rum/jsLatestVersion");
  if (!targetVersion) throw new Error("Could not resolve effective target RUM Classic JS version from configured policy");

  const enriched = await mapConcurrent(manualApps, 5, async (app) => {
    const applicationId = app.applicationId;
    const displayName = app.displayName || applicationId;
    const jsVersion = await dtGetText(`${baseUrl}/api/v1/rum/appRevision/${applicationId}`);
    const javaScriptTag = await dtTryGetText(`${baseUrl}/api/v2/rum/javaScriptTag/${applicationId}`);
    const inlineCode = javaScriptTag ? "" : await dtTryGetText(`${baseUrl}/api/v2/rum/inlineCode/${applicationId}`);
    let humanReadableTargetLabel = extractHumanReadableVersionLabel(javaScriptTag || inlineCode);
    if (!humanReadableTargetLabel) {
      humanReadableTargetLabel = jsVersion;
    }
    return { applicationId, displayName, jsVersion, humanReadableTargetLabel };
  });

  let effectiveTargetLabel = summarizeTargetLabel(enriched);
  if (!effectiveTargetLabel) {
    effectiveTargetLabel = targetVersion;
  }
  const ingestUrl = `${baseUrl}/api/v2/events/ingest`;

  await dtPostJson(ingestUrl, {
    eventType: "CUSTOM_ANNOTATION",
    title: `RUMJSBaseline|${latestVersion}|${oldestSupportedVersion}|${fetchedAt}`,
    description: "RUM Classic JS baseline sync (latest, oldest supported, and effective target)",
    properties: {
      source: "rum_classic_baseline",
      latest_version: latestVersion,
      oldest_supported_version: oldestSupportedVersion,
      support_floor_known: supportFloorVersion ? "true" : "false",
      effective_target_version: targetVersion,
      effective_target_policy: targetPolicy,
      effective_target_label: effectiveTargetLabel,
      latest_stable: normalizeVersion(configuredVersions.latestStable),
      previous_stable: normalizeVersion(configuredVersions.previousStable),
      latest_ie_supported: normalizeVersion(configuredVersions.latestIESupported),
      latest_ie11_supported: normalizeVersion(configuredVersions.latestIE11Supported),
      custom_configured_version: normalizeVersion(configuredVersions.custom),
      fetched_at: fetchedAt
    }
  });

  await mapConcurrent(enriched, 5, async (app) => {
    let label = normalizeVersion(app.humanReadableTargetLabel);
    if (!label) label = app.jsVersion;
    await dtPostJson(ingestUrl, {
      eventType: "CUSTOM_ANNOTATION",
      title: `RUMJSVersion|${app.applicationId}|${app.jsVersion}|${fetchedAt}`,
      description: `RUM Classic JS library version for ${app.displayName}`,
      properties: {
        source: "rum_classic_api",
        application_id: app.applicationId,
        application_name: app.displayName,
        js_library_version: app.jsVersion,
        human_readable_target_label: label,
        fetched_at: fetchedAt
      }
    });
  });

  const byVersion = {};
  const policyCounts = {
    on_target: 0,
    below_target: 0,
    unsupported: 0,
    above_target: 0,
    unknown: 0
  };

  for (const app of enriched) {
    byVersion[app.jsVersion] = (byVersion[app.jsVersion] || 0) + 1;
    const status = computePolicyStatus(app.jsVersion, targetVersion, supportFloorVersion);
    policyCounts[status] = (policyCounts[status] || 0) + 1;
  }

  await mapConcurrent(enriched, 5, async (app) => {
    const status = computePolicyStatus(app.jsVersion, targetVersion, supportFloorVersion);
    let label = normalizeVersion(app.humanReadableTargetLabel);
    if (!label) label = app.jsVersion;
    await dtPostJson(ingestUrl, {
      eventType: "CUSTOM_ANNOTATION",
      title: `RUMJSPolicyApp|${app.applicationId}|${status}|${fetchedAt}`,
      description: `RUM Classic JS policy status for ${app.displayName}`,
      properties: {
        source: "rum_classic_policy_app",
        application_id: app.applicationId,
        application_name: app.displayName,
        js_library_version: app.jsVersion,
        human_readable_target_label: label,
        effective_target_version: targetVersion,
        effective_target_policy: targetPolicy,
        effective_target_label: effectiveTargetLabel,
        latest_version: latestVersion,
        oldest_supported_version: oldestSupportedVersion,
      support_floor_known: supportFloorVersion ? "true" : "false",
        policy_status: status,
        fetched_at: fetchedAt
      }
    });
  });

  await dtPostJson(ingestUrl, {
    eventType: "CUSTOM_ANNOTATION",
    title: `RUMJSVersionSyncSummary|${enriched.length}|${Object.keys(byVersion).length}|${fetchedAt}`,
    description: "RUM Classic JS version sync summary",
    properties: {
      source: "rum_classic_api",
      app_count: String(enriched.length),
      versions_found: String(Object.keys(byVersion).length),
      fetched_at: fetchedAt
    }
  });

  await dtPostJson(ingestUrl, {
    eventType: "CUSTOM_ANNOTATION",
    title: `RUMJSPolicySummary|${policyCounts.on_target}|${policyCounts.below_target}|${policyCounts.unsupported}|${fetchedAt}`,
    description: "RUM Classic JS policy status summary",
    properties: {
      source: "rum_classic_policy_summary",
      apps_on_target: String(policyCounts.on_target),
      apps_below_target: String(policyCounts.below_target),
      apps_unsupported: String(policyCounts.unsupported),
      apps_above_target: String(policyCounts.above_target),
      apps_unknown: String(policyCounts.unknown),
      effective_target_version: targetVersion,
      effective_target_policy: targetPolicy,
      effective_target_label: effectiveTargetLabel,
      latest_version: latestVersion,
      oldest_supported_version: oldestSupportedVersion,
      support_floor_known: supportFloorVersion ? "true" : "false",
      fetched_at: fetchedAt
    }
  });

  return {
    fetched_at: fetchedAt,
    latest_version: latestVersion,
    oldest_supported_version: oldestSupportedVersion,
    effective_target_version: targetVersion,
    effective_target_policy: targetPolicy,
    effective_target_label: effectiveTargetLabel,
    app_count: enriched.length,
    versions_found: Object.keys(byVersion).length,
    policy_status: policyCounts,
    by_version: byVersion
  };
}

import { execution } from "@dynatrace-sdk/automation-utils";

async function getText(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`HTTP ${resp.status} for ${url}`);
  return await resp.text();
}

function uniqueBy(items, keyFn) {
  const out = [];
  const seen = new Set();
  for (const i of items) {
    const k = keyFn(i);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(i);
  }
  return out;
}

function compareSemverDesc(a, b) {
  const pa = a.split('.').map((n) => Number(n));
  const pb = b.split('.').map((n) => Number(n));
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i += 1) {
    const av = pa[i] || 0;
    const bv = pb[i] || 0;
    if (av !== bv) return bv - av;
  }
  return 0;
}

function parseLatestFromSitemap(sitemap, component) {
  const urls = [...sitemap.matchAll(new RegExp(`<loc>(https://docs\.dynatrace\.com/docs/whats-new/${component.path}/[^<]+)</loc>`, 'g'))]
    .map((m) => m[1]);

  if (!urls.length) {
    return null;
  }

  if (component.mode === 'sprint') {
    const entries = uniqueBy(
      urls
        .map((u) => {
          const m = u.match(/\/sprint-(\d+)/);
          if (!m) return null;
          return { url: u, sprint: Number(m[1]), version: `1.${Number(m[1])}` };
        })
        .filter(Boolean),
      (e) => e.url
    );

    if (!entries.length) return null;
    entries.sort((a, b) => b.sprint - a.sprint);
    return entries[0];
  }

  if (component.mode === 'operator_semver') {
    const entries = uniqueBy(
      urls
        .map((u) => {
          const m = u.match(/dto-fix-(\d+)-(\d+)-(\d+)/);
          if (!m) return null;
          return { url: u, version: `${Number(m[1])}.${Number(m[2])}.${Number(m[3])}` };
        })
        .filter(Boolean),
      (e) => e.url
    );
    if (!entries.length) return null;
    entries.sort((a, b) => compareSemverDesc(a.version, b.version));
    return entries[0];
  }

  if (component.mode === 'edgeconnect_semver') {
    const entries = uniqueBy(
      urls
        .map((u) => {
          const m = u.match(/edgeconnect-release-notes-(\d+)-(\d+)-(\d+)/);
          if (!m) return null;
          return { url: u, version: `${Number(m[1])}.${Number(m[2])}.${Number(m[3])}` };
        })
        .filter(Boolean),
      (e) => e.url
    );
    if (!entries.length) return null;
    entries.sort((a, b) => compareSemverDesc(a.version, b.version));
    return entries[0];
  }

  return null;
}

export default async function () {
  await execution();

  const components = [
    { component: 'saas', path: 'saas', mode: 'sprint', index_url: 'https://docs.dynatrace.com/docs/whats-new/saas' },
    { component: 'oneagent', path: 'oneagent', mode: 'sprint', index_url: 'https://docs.dynatrace.com/docs/whats-new/oneagent' },
    { component: 'activegate', path: 'activegate', mode: 'sprint', index_url: 'https://docs.dynatrace.com/docs/whats-new/activegate' },
    { component: 'operator', path: 'dynatrace-operator', mode: 'operator_semver', index_url: 'https://docs.dynatrace.com/docs/whats-new/dynatrace-operator' },
    { component: 'edgeconnect', path: 'edgeconnect', mode: 'edgeconnect_semver', index_url: 'https://docs.dynatrace.com/docs/whats-new/edgeconnect' }
  ];

  const fetched_at = new Date().toISOString();
  const release_rows = [];
  const docsSitemapUrlUi = "{{ event().inputs.docsSitemapUrl }}";
  const docsSitemapUrl = (!docsSitemapUrlUi || docsSitemapUrlUi.startsWith("{{")) ? "https://docs.dynatrace.com/docs/sitemap.xml" : docsSitemapUrlUi;

  const sitemap = await getText(docsSitemapUrl);

  for (const c of components) {
    const latest = parseLatestFromSitemap(sitemap, c);

    release_rows.push({
      component: c.component,
      released_version: latest ? latest.version : '',
      release_status: latest ? 'current' : 'unavailable',
      rollout_start_date: '',
      is_latest: 'true',
      is_next_planned: 'false',
      release_url: latest ? latest.url : c.index_url,
      index_url: c.index_url,
      fetched_at
    });

    release_rows.push({
      component: c.component,
      released_version: 'Not yet published',
      release_status: 'not_yet_published',
      rollout_start_date: '',
      is_latest: 'false',
      is_next_planned: 'true',
      release_url: c.index_url,
      index_url: c.index_url,
      fetched_at
    });
  }

  const summary_prompt = release_rows
    .filter((r) => r.is_latest === 'true')
    .map((r) => `${r.component}: ${r.released_version || 'unavailable'} ${r.release_url}`)
    .join(String.fromCharCode(10));

  return { fetched_at, release_rows, summary_prompt };
}

import { execution } from "@dynatrace-sdk/automation-utils";
import { credentialVaultClient } from "@dynatrace-sdk/client-classic-environment-v2";
import { getEnvironmentUrl } from "@dynatrace-sdk/app-environment";

const API_TOKEN_VAULT_ID_UI = "{{ event().inputs.apiTokenVaultId }}";
const API_TOKEN_VAULT_ID = (!API_TOKEN_VAULT_ID_UI || API_TOKEN_VAULT_ID_UI.startsWith("{{")) ? "CREDENTIALS_VAULT-152083F2EC7D5E4B" : API_TOKEN_VAULT_ID_UI;

async function resolveToken(id) {
  const credentials = await credentialVaultClient.getCredentialsDetails({ id });
  if (!credentials || !credentials.token) throw new Error(`No token in vault ${id}`);
  return credentials.token;
}

export default async function () {
  await execution();
  const fetched_at = new Date().toISOString();
  try {
    const apiToken = await resolveToken(API_TOKEN_VAULT_ID);
    const envUrl = (getEnvironmentUrl() || "").trim();
    const env = new URL(envUrl);
    env.host = env.host.replace(".apps.", ".");
    env.pathname = "/api/v1/config/clusterversion";
    env.search = "";
    env.hash = "";

    const resp = await fetch(env.toString(), { headers: { Authorization: `Api-Token ${apiToken}` } });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const body = await resp.json();

    return {
      runtime_rows: [{
        component: "saas",
        observed_version: String(body.version || ""),
        running_count: "1",
        source_type: "cluster_version_api",
        source_status: "current",
        observed_at: fetched_at,
        collection_message: ""
      }]
    };
  } catch (error) {
    return {
      runtime_rows: [{
        component: "saas",
        observed_version: "",
        running_count: "0",
        source_type: "cluster_version_api",
